import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {keepPreviousData, useQuery} from '@github-ui/react-query'
import {AiModelIcon} from '@primer/octicons-react'
import {ActionList, Button, Dialog, Textarea} from '@primer/react'
import {Banner} from '@primer/react/experimental'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useCodespaceContext} from '../../../contexts/CodespaceContext'
import {useFilesContext} from '../../../contexts/FilesContext'
import {useFileSyncerContext} from '../../../contexts/FileSyncerContext'
import {useFetchFromCodespaceApi} from '../../../hooks/use-fetch-from-codespace-api'
import {ReadOnlyKey, useReadOnly} from '../../../hooks/use-read-only'
import {useIterateAnalytics} from '../../../telemetry/use-analytics'
import {Section} from '../Section'
import styles from './AiPanel.module.css'

export interface AiPanelProps {
  isFetching: boolean
  workbenchId: string
}

type Prompt = {
  file: string
  description: string
  uniqueFileId: string
}

type File = {
  file: string
  originalContents: string
}

const FILE_EXTENSIONS = ['.js', '.ts', '.jsx', '.tsx']
const RETRY_COUNT = 5

function normalizeWhitespaceForComparison(str: string): string {
  return str
    .replace(/\r\n/g, '\n') // Normalize line endings
    .replace(/\t/g, ' ') // Convert tabs to spaces
    .replace(/\s+/g, ' ') // Collapse all whitespace to single spaces
    .trim() // Remove leading/trailing whitespace
}

export function AiPanel({workbenchId}: AiPanelProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const [oldPrompts, setPrompts] = useState<Prompt[]>([])
  const [files, setFiles] = useState<File[]>([])
  const [isFetchingFiles, setIsFetchingFiles] = useState(true)
  const [isProcessingFiles, setIsProcessingFiles] = useState(true)
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [selectedPrompt, setSelectedPrompt] = useState<Prompt | null>(null)
  const [promptContent, setPromptContent] = useState('')
  const [promptUpdateError, setPromptUpdateError] = useState<string | null>(null)
  const richAiPromptParsingEnabled = useFeatureFlag('copilot_workbench_rich_ai_prompt_parsing')
  const {fetchFromCodespaceApi} = useFetchFromCodespaceApi()
  const {getFileSyncerV2, forceContentRefresh, lastEditStateStamp} = useFileSyncerContext()
  const {
    codespaceData: {codespaceState},
  } = useCodespaceContext()
  const isCodespaceReady = codespaceState === 'ready'
  const isAssetsV2 = useFeatureFlag('spark_assets_include_media')

  const {getFileList, editFile} = useFilesContext()
  const readOnly = useReadOnly(ReadOnlyKey.AI_PANEL)

  const resetDialogState = useCallback(() => {
    setIsDialogOpen(false)
    setSelectedPrompt(null)
    setPromptContent('')
  }, [])

  useEffect(() => {
    if (richAiPromptParsingEnabled) {
      setIsFetchingFiles(false)
      setIsProcessingFiles(false)
      return
    }
    // Gets files that should be scraped for prompts
    const fetchFilesAndPrompts = async () => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer) {
        setIsFetchingFiles(false)
        return
      }

      setIsFetchingFiles(true)
      const fetchedFiles = getFileList()
      // Filter out directories and files that don't match the extensions
      const filteredFiles = fetchedFiles.filter(
        file => file.type === 'file' && FILE_EXTENSIONS.some(fileExtension => file.path.endsWith(fileExtension)),
      )
      // Get original content for each file
      const fileContents = await Promise.all(
        filteredFiles.map(async file => {
          const content = await fileSyncer.readFileString(file.path, isAssetsV2)
          return {file: file.path, originalContents: content}
        }),
      )

      setIsFetchingFiles(false)
      setFiles(fileContents)
    }
    fetchFilesAndPrompts()
  }, [workbenchId, lastEditStateStamp, getFileSyncerV2, getFileList, richAiPromptParsingEnabled, isAssetsV2])

  const fetchPrompts = useCallback(async () => {
    setIsFetchingFiles(false)
    if (oldPrompts.length === 0) {
      // Only set the loading state if we are fetching prompts for the first time
      // to avoid having it flashing in and out as the user types.
      setIsProcessingFiles(true)
    }
    try {
      const res = await fetchFromCodespaceApi('/prompts')

      if (!res.ok) {
        setIsProcessingFiles(false)
        throw new Error(`Failed to fetch prompts: ${res.statusText}`)
      }

      const json: {data: {prompts: Prompt[]}} = await res.json()
      setIsProcessingFiles(false)
      setPrompts(json.data.prompts)
      return json.data.prompts
    } finally {
      setIsProcessingFiles(false)
    }
  }, [fetchFromCodespaceApi, oldPrompts.length])

  const {
    data: cachedPrompts,
    isLoading,
    isError,
    refetch,
  } = useQuery<Prompt[]>({
    enabled: richAiPromptParsingEnabled && isCodespaceReady,
    queryKey: ['fetchPrompts', lastEditStateStamp, isCodespaceReady],
    queryFn: async () => await fetchPrompts(),
    placeholderData: keepPreviousData,
    staleTime: Infinity,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
    refetchOnReconnect: false,
    refetchInterval: false,
    retry: RETRY_COUNT,
  })

  const prompts = richAiPromptParsingEnabled ? cachedPrompts ?? [] : oldPrompts
  const isWaitingForCodespace = richAiPromptParsingEnabled && !isCodespaceReady
  const loading = useMemo(() => {
    if (richAiPromptParsingEnabled) {
      return isLoading || isWaitingForCodespace
    }

    return isFetchingFiles || isProcessingFiles || isWaitingForCodespace
  }, [richAiPromptParsingEnabled, isFetchingFiles, isLoading, isProcessingFiles, isWaitingForCodespace])

  const processFiles = useCallback(async () => {
    const newPrompts: Prompt[] = []
    const fileSyncer = getFileSyncerV2()
    if (!fileSyncer) {
      setIsFetchingFiles(false)
      return
    }

    setIsProcessingFiles(true)

    // Gets content of each file and checks for / extracts prompts
    for (const {file} of files) {
      const fileContent = await fileSyncer.readFileString(file, isAssetsV2)

      if (fileContent) {
        let currentIndex = 0
        let promptCount = 0

        while (true) {
          const startIndex = fileContent.indexOf('spark.llmPrompt`', currentIndex)
          if (startIndex === -1) break

          const promptStartIndex = startIndex + 'spark.llmPrompt`'.length
          const endIndex = fileContent.indexOf('`', promptStartIndex)

          if (endIndex !== -1) {
            const prompt = fileContent.substring(promptStartIndex, endIndex)
            newPrompts.push({
              file,
              description: prompt,
              uniqueFileId: `${file}${promptCount > 0 ? ` (${promptCount + 1})` : ''}`,
            })
            promptCount++
            currentIndex = endIndex + 1
          }
        }
      }
    }

    setIsProcessingFiles(false)
    setPrompts(newPrompts)
  }, [files, getFileSyncerV2, isAssetsV2])

  useEffect(() => {
    if (richAiPromptParsingEnabled) {
      return
    } else {
      processFiles()
    }
  }, [processFiles, lastEditStateStamp, richAiPromptParsingEnabled, fetchPrompts, isCodespaceReady])

  const {iterateStarted, iterateSuccess} = useIterateAnalytics('ai_panel')

  const handleUpdate = async (file: string, previousPrompt: string, newPrompt: string) => {
    setPromptUpdateError(null)
    const originalContent = files.find(f => f.file === file)?.originalContents
    const fileSyncer = getFileSyncerV2()
    if (!fileSyncer) return
    const fileContent = await fileSyncer.readFileString(file, isAssetsV2)

    if (fileContent) {
      const telemetryProperties = iterateStarted()

      // Use regex-based replacement for more flexible matching
      const normalizedPrevious = normalizeWhitespaceForComparison(previousPrompt)

      // Create a regex that matches the prompt with flexible whitespace
      const escapedPrompt = normalizedPrevious.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      const flexiblePromptRegex = new RegExp(escapedPrompt.replace(/\s+/g, '\\s+'), 'g')

      if (!flexiblePromptRegex.test(fileContent)) {
        setPromptUpdateError(`Could not find the prompt to replace. Please update ${file} directly.`)
        return
      }

      // Perform the replacement
      const newContent = fileContent.replace(flexiblePromptRegex, newPrompt)

      await editFile({filePath: file, originalContent, newFileContent: newContent})
      setSelectedPrompt(null)
      setPromptContent('')
      setIsDialogOpen(false)
      forceContentRefresh()
      if (!richAiPromptParsingEnabled) {
        processFiles()
      }

      iterateSuccess(telemetryProperties)
    }
  }

  const handlePromptClick = (prompt: Prompt) => {
    setSelectedPrompt(prompt)
    setPromptContent(prompt.description)
    setIsDialogOpen(true)
  }

  const handleDescriptionChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setPromptContent(e.target.value)
  }

  return (
    <div className="mt-3">
      <Section title="Prompts" showTitle={false} readOnly={readOnly} loading={loading}>
        <Section.Items>
          <p className="fgColor-muted text-small">
            Add AI capabilities by asking in the Iterate panel. View and edit the prompts powering those features here.
          </p>
        </Section.Items>

        {isError && richAiPromptParsingEnabled && (
          <Banner
            title="We couldn't load your data"
            description="Please try again. If the problem persists, try again later."
            variant="critical"
            primaryAction={
              <Button loading={isLoading} onClick={() => refetch()}>
                Retry
              </Button>
            }
          />
        )}

        {prompts.length > 0 && (
          <ActionList className={styles.actionList}>
            {prompts.map(prompt => {
              const id = prompt.uniqueFileId.replace(/[^a-zA-Z0-9]/g, '-').replace(/-+/g, '-')
              return (
                <ActionList.Item
                  className={styles.listItem}
                  key={id}
                  id={`edit-${id}`}
                  onSelect={() => handlePromptClick(prompt)}
                >
                  <ActionList.LeadingVisual>
                    <AiModelIcon />
                  </ActionList.LeadingVisual>
                  {prompt.uniqueFileId}
                  <ActionList.Description variant="block">
                    <span className="line-clamp-2">{prompt.description}</span>
                  </ActionList.Description>
                </ActionList.Item>
              )
            })}
          </ActionList>
        )}
        {isDialogOpen && selectedPrompt && (
          <Dialog
            title="Edit prompt"
            footerButtons={[
              {
                buttonType: 'default',
                content: 'Cancel',
                onClick: resetDialogState,
              },
              {
                buttonType: 'primary',
                content: 'Update',
                disabled: readOnly,
                onClick: async () => await handleUpdate(selectedPrompt.file, selectedPrompt.description, promptContent),
              },
            ]}
            onClose={resetDialogState}
          >
            <Textarea block ref={textareaRef} value={promptContent} onChange={handleDescriptionChange} rows={15} />
            {promptUpdateError && (
              <Banner
                hideTitle
                variant="critical"
                title="Unable to update prompt"
                aria-label="Critical"
                description={promptUpdateError}
              />
            )}
          </Dialog>
        )}
      </Section>
    </div>
  )
}

try{ AiPanel.displayName ||= 'AiPanel' } catch {}